import type { OffscreenStartRequest, RuntimeMessage } from "../shared/schema";

let mediaRecorder: MediaRecorder | null = null;
let mediaStream: MediaStream | null = null;
let chunks: Blob[] = [];
let mimeType = "video/webm;codecs=vp9,opus";
let objectUrl = "";

const stopTracks = (): void => {
  for (const track of mediaStream?.getTracks() ?? []) {
    track.stop();
  }
  mediaStream = null;
};

const releaseCapture = (): void => {
  if (mediaRecorder && mediaRecorder.state !== "inactive") {
    try {
      mediaRecorder.stop();
    } catch {
      // The recorder may already be stopping.
    }
  }

  mediaRecorder = null;
  stopTracks();
  chunks = [];
};

const getSupportedMimeType = (): string => {
  const candidates = ["video/webm;codecs=vp9,opus", "video/webm;codecs=vp8,opus", "video/webm"];
  return candidates.find((candidate) => MediaRecorder.isTypeSupported(candidate)) ?? "video/webm";
};

const startRecording = async (message: OffscreenStartRequest): Promise<void> => {
  releaseCapture();

  if (objectUrl) {
    URL.revokeObjectURL(objectUrl);
    objectUrl = "";
  }

  mimeType = getSupportedMimeType();

  mediaStream = await navigator.mediaDevices.getUserMedia({
    audio: {
      mandatory: {
        chromeMediaSource: "tab",
        chromeMediaSourceId: message.streamId
      }
    } as MediaTrackConstraints,
    video: {
      mandatory: {
        chromeMediaSource: "tab",
        chromeMediaSourceId: message.streamId
      }
    } as MediaTrackConstraints
  });

  mediaRecorder = new MediaRecorder(mediaStream, { mimeType });
  mediaRecorder.ondataavailable = (event) => {
    if (event.data.size > 0) {
      chunks.push(event.data);
    }
  };
  mediaRecorder.start(1000);
};

const stopRecording = async (): Promise<{ mimeType: string; objectUrl: string; sizeBytes: number }> => {
  if (!mediaRecorder || mediaRecorder.state === "inactive") {
    stopTracks();
    const inactiveBlob = new Blob(chunks, { type: mimeType });
    objectUrl = URL.createObjectURL(inactiveBlob);
    chunks = [];
    mediaRecorder = null;
    return {
      mimeType,
      objectUrl,
      sizeBytes: inactiveBlob.size
    };
  }

  await new Promise<void>((resolve) => {
    if (!mediaRecorder) {
      resolve();
      return;
    }

    mediaRecorder.onstop = () => resolve();
    mediaRecorder.stop();
  });

  const blob = new Blob(chunks, { type: mimeType });
  releaseCapture();
  objectUrl = URL.createObjectURL(blob);

  return {
    mimeType,
    objectUrl,
    sizeBytes: blob.size
  };
};

chrome.runtime.onMessage.addListener((message: RuntimeMessage, _sender, sendResponse) => {
  if (message.type === "OFFSCREEN_START") {
    startRecording(message)
      .then(() => sendResponse({ ok: true }))
      .catch((error: unknown) => sendResponse({ ok: false, error: error instanceof Error ? error.message : String(error) }));
    return true;
  }

  if (message.type === "OFFSCREEN_RELEASE") {
    releaseCapture();
    sendResponse({ ok: true });
    return false;
  }

  if (message.type === "OFFSCREEN_STOP") {
    stopRecording()
      .then((payload) => sendResponse({ ok: true, payload }))
      .catch((error: unknown) => sendResponse({ ok: false, error: error instanceof Error ? error.message : String(error) }));
    return true;
  }

  return false;
});
